.begin-button span{float:right;font-size:17px;margin-top:-3px}
.intro-foot{display:flex;gap:9px;margin-top:20px;color:#82948a;font:8px 'DM Mono';letter-spacing:.5px}
.intro-caption{position:absolute;right:31px;bottom:25px;left:31px;display:flex;justify-content:space-between;color:rgba(240,245,239,.67);font:8px 'DM Mono';letter-spacing:1px}
.modal-backdrop{position:absolute;inset:0;background:rgba(7,13,16,.68);backdrop-filter:blur(5px);z-index:7;display:none;align-items:center;justify-content:center}
.modal-backdrop.open{display:flex}
.modal{position:relative;width:min(460px,calc(100vw - 32px));padding:27px;background:rgba(19,31,34,.97);border:1px solid rgba(226,238,231,.17);border-radius:8px;box-shadow:0 25px 90px rgba(0,0,0,.45)}
.modal-close{position:absolute;right:15px;top:13px;background:transparent;border:0;color:#b6c3bc;font-size:24px;cursor:pointer}
.modal-kicker{font:9px 'DM Mono';letter-spacing:1.2px;color:#a4d3b2}
.modal h2{font:600 26px Manrope;letter-spacing:-.8px;margin:9px 0}
.modal p{font-size:12px;line-height:1.65;color:#b6c2bb}
.modal-options{display:flex;flex-direction:column;gap:8px;margin-top:18px}
.choice{width:100%;text-align:left;padding:12px 13px;border-radius:4px;border:1px solid rgba(255,255,255,.13);background:rgba(255,255,255,.045);cursor:pointer;transition:.2s}
.choice:hover{border-color:rgba(182,223,199,.55);background:rgba(182,223,199,.09)}
.choice strong{display:block;font:600 11px Manrope;color:#e7ede7}
.choice small{display:block;margin-top:4px;font-size:10px;color:#9caca4;line-height:1.4}
.modal-stats{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin:17px 0}
.modal-stat{padding:11px;background:rgba(255,255,255,.045);border:1px solid rgba(255,255,255,.08);border-radius:4px}
.modal-stat small{display:block;color:#9aaba2;font:8px 'DM Mono';letter-spacing:.7px}
.modal-stat strong{display:block;margin-top:5px;font:600 13px Manrope}
.event-feed{max-height:250px;overflow:auto}
.event-line{padding:10px 0;border-bottom:1px solid rgba(255,255,255,.08);font-size:11px;line-height:1.5;color:#c2cdc5}
.event-line small{display:block;color:#8da297;font:8px 'DM Mono';margin-bottom:4px}
@media(max-width:850px){.left-rail,.right-rail{width:205px}
.left-rail{left:12px}
.right-rail{right:12px}
.bottom-center{width:calc(100% - 460px);min-width:320px}
.topbar{padding:0 17px}
.world-label{font-size:8px}
}
@media(max-width:650px){.topbar{height:59px;padding:0 12px}
.world-label{display:none}
.left-rail{top:70px;left:9px;width:168px;gap:6px}
.right-rail{top:70px;right:9px;width:155px;gap:6px}
.profile-card{padding:9px}
.avatar{width:29px;height:29px}
.profile-copy strong{font-size:9px}
.profile-copy small{font-size:8px}
.needs-card,.wallet-card,.journal-card,.clock-card,.world-card,.controls-card{padding:9px}
.need-row{grid-template-columns:42px 1fr 17px;gap:5px;font-size:8px;margin:8px 0}
.section-title{font-size:8px;margin-bottom:9px}
.journal-card{min-height:120px}
.log-item{font-size:8px;padding:6px 0;grid-template-columns:27px 1fr}
.clock-card>strong{font-size:28px}
.world-card p{font-size:9px}
.statline{font-size:8px}
.controls-card>div:not(.section-title){height:21px;font-size:8px}
.controls-card kbd{font-size:7px;padding:3px}
.bottom-center{bottom:13px;width:calc(100% - 18px);min-width:0}
.objective{height:57px;padding:0 9px;gap:7px}
.objective small{font-size:7px}
.objective strong{font-size:9px}
.objective button{font-size:7px;padding-left:7px}
.location-toast{bottom:84px;left:9px;padding:7px}
.intro-card{margin-left:7%;width:86%}
.intro-brand{margin-bottom:37px}
.intro-card h1{font-size:52px}
.intro-card>p{font-size:12px;max-width:345px}
.intro-meta{gap:20px}
.intro-caption{left:12px;right:12px;font-size:7px}
.intro-foot{font-size:7px;gap:5px}
.begin-button{width:min(290px,100%)}
}

