368: function animateNPCs(t,dt){
369:   for(const p of world.people){
370:     const mesh=p.mesh,limbs=p.limbs;
371:     const walking=p.routine.includes('way')||p.routine.includes('errand')||p.routine.includes('heading');
372:     if(walking&&Math.hypot(p.x-player.position.x,p.z-player.position.z)>4){
373:       if(!p.target||Math.hypot(p.target.x-p.x,p.target.z-p.z)<.55){
374:         const angle=rng()*Math.PI*2,distance=2+rng()*5;
375:         p.target={x:Math.max(-100,Math.min(100,p.x+Math.sin(angle)*distance)),z:Math.max(-77,Math.min(77,p.z+Math.cos(angle)*distance))};
376:       }
377:       const dx=p.target.x-p.x,dz=p.target.z-p.z,distance=Math.hypot(dx,dz),step=Math.min(distance,.7*dt);
378:       if(distance>.1&&!blocked(p.x+dx/distance*step,p.z+dz/distance*step)){
379:         p.x+=dx/distance*step;p.z+=dz/distance*step;mesh.rotation.y=Math.atan2(dx,-dz);
380:       }else p.target=null;
381:     }
382:     const gait=walking?Math.sin(t*7+p.walkSeed):Math.sin(t*1.4+p.walkSeed)*.08;
383:     limbs.legs.forEach((limb,i)=>limb.rotation.x=walking?gait*(i===0?-.48:.48):0);
384:     limbs.arms.forEach((limb,i)=>limb.rotation.x=walking?gait*(i===0?.34:-.34):Math.sin(t*1.2+p.walkSeed+i)*.025);
385:     mesh.position.set(p.x,Math.abs(gait)*.025,p.z);
386:     if(!walking)mesh.rotation.y=Math.sin(t*.2+p.walkSeed)*.025;
387:   }
388: }
